head.script:
scwin.trigger1_onclick = function(e) {
    inputCalendar1.setDefaultDate("20160102030405");
};
scwin.trigger2_onclick = function(e) {
    inputCalendar2.setDefaultDate("2016010203");
};
scwin.trigger3_onclick = function(e) {
    inputCalendar3.setDefaultDate("201601020304");
};
scwin.trigger4_onclick = function(e) {
    inputCalendar4.setDefaultDate("20160102");
};
scwin.trigger5_onclick = function(e) {
    inputCalendar1.setDefaultDate("20170102060708");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 1번 클릭 후 달력버튼을 클릭한다.
    //1. Run the sample file and click the calendar button after one click.
    //Verify 1. 2016년 1월 2일 3시 4분 5초가 보여진다.
    //1. January 2, 2016 shows 3:04:52.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_year_label').innerText == '2016년'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_year').selectedIndex == '38'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_month_label').innerText == '1월'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_month').selectedIndex == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar1_calendar_cell_0_6').hasClass('w2calendar_selected')", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_hour_label').innerText == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_hour').selectedIndex == '3'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_minute_label').innerText == '4'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_minute').selectedIndex == '4'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_second_label').innerText == '5'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_second').selectedIndex == '5'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 2. 2번 클릭 후 달력버튼을 클릭한다.
    //2. Click twice and then click the calendar button.
    //Verify 2. 2016년 1월 2일 3시가 보여진다.
    //2. January 3, 2016 is shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_year_label').innerText == '2016년'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_year').selectedIndex == '38'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_month_label').innerText == '1월'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_month').selectedIndex == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar2_calendar_cell_0_6').hasClass('w2calendar_selected')", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_hour_label').innerText == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_hour').selectedIndex == '3'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 3. 3번 클릭 후 달력버튼을 클릭한다.
    //3. Click on the calendar button after 3 clicks.
    //Verify 3. 2016년 1월 2일 3시 4분이 보여진다.
    //3. It is seen on January 2, 2016 at 3: 4.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_img').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_year_label').innerText == '2016년'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_year').selectedIndex == '38'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_month_label').innerText == '1월'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_month').selectedIndex == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar3_calendar_cell_0_6').hasClass('w2calendar_selected')", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_hour_label').innerText == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_hour').selectedIndex == '3'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_minute_label').innerText == '4'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_minute').selectedIndex == '4'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 4. 4번 클릭 후 달력버튼을 클릭한다.
    //4. Click the calendar button after 4 clicks.
    //Verify 4. 2016년 1월 2일이 보여진다.
    //4. January 2, 2016 is shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar4_img').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar4_calendar_selectbox_year_label').innerText == '2016년'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar4_calendar_selectbox_year').selectedIndex == '38'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar4_calendar_selectbox_month_label').innerText == '1월'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar4_calendar_selectbox_month').selectedIndex == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar4_calendar_cell_0_6').hasClass('w2calendar_selected')", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 5. 5번 클릭 후 달력버튼을 클릭한다.
    //5. After 5 clicks, click the calendar button.
    //Verify 5. 2016년 1월 2일 6시 7분 8초가 보여진다.
    //5. January 6, 2016, 6:07:08 is shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_month_label').innerText == '1월'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_month').selectedIndex == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar1_calendar_cell_1_1').hasClass('w2calendar_selected')", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_hour_label').innerText == '6'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_hour').selectedIndex == '6'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_minute_label').innerText == '7'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_minute').selectedIndex == '7'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_second_label').innerText == '8'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_selectbox_second').selectedIndex == '8'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run and Stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 09-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
